"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

interface KillFeedEntry {
  killer: string;
  killerTeam: "ct" | "t";
  victim: string;
  victimTeam: "ct" | "t";
  weapon: string;
  headshot?: boolean;
}

interface KillFeedProps extends React.HTMLAttributes<HTMLDivElement> {
  entries: KillFeedEntry[];
  maxVisible?: number;
}

const WEAPON_SYMBOLS: Record<string, string> = {
  ak47: "AK-47",
  m4a1: "M4A1",
  awp: "AWP",
  deagle: "Deagle",
  usp: "USP",
  glock: "Glock",
  knife: "Knife",
  hegrenade: "HE",
  flashbang: "Flash",
  smokegrenade: "Smoke",
  mp5: "MP5",
  p90: "P90",
  scout: "Scout",
  aug: "AUG",
  sg552: "SG552",
  famas: "Famas",
  galil: "Galil",
  mac10: "MAC-10",
  ump45: "UMP",
  m249: "M249",
  xm1014: "XM1014",
  m3: "M3",
  elite: "Dual Elites",
  fiveseven: "Five-SeveN",
  p228: "P228",
  tmp: "TMP",
  g3sg1: "G3SG1",
  sg550: "SG550",
};

const KillFeed = React.forwardRef<HTMLDivElement, KillFeedProps>(
  ({ className, entries, maxVisible = 5, ...props }, ref) => {
    const visible = entries.slice(0, maxVisible);

    return (
      <div
        ref={ref}
        className={cn("flex flex-col items-end gap-0.5", className)}
        {...props}
      >
        {visible.map((entry, i) => (
          <div
            key={i}
            className={cn(
              "flex items-center gap-1.5 px-2 py-0.5",
              "bg-black/50 backdrop-blur-sm",
              i === 0 && "opacity-100",
              i === 1 && "opacity-90",
              i === 2 && "opacity-75",
              i === 3 && "opacity-55",
              i === 4 && "opacity-35"
            )}
          >
            <span
              className={cn(
                "cs-font-ui text-xs cs-text-shadow",
                entry.killerTeam === "ct"
                  ? "text-[var(--cs-team-ct)]"
                  : "text-[var(--cs-team-t)]"
              )}
            >
              {entry.killer}
            </span>

            <span className="cs-font-ui text-[10px] text-[var(--cs-text-dim)] px-1">
              [{WEAPON_SYMBOLS[entry.weapon] || entry.weapon}]
            </span>

            {entry.headshot && (
              <span className="text-[10px] text-[var(--cs-hud-amber)]" title="Headshot">
                HS
              </span>
            )}

            <span
              className={cn(
                "cs-font-ui text-xs cs-text-shadow",
                entry.victimTeam === "ct"
                  ? "text-[var(--cs-team-ct)]"
                  : "text-[var(--cs-team-t)]"
              )}
            >
              {entry.victim}
            </span>
          </div>
        ))}
      </div>
    );
  }
);
KillFeed.displayName = "KillFeed";

export { KillFeed, type KillFeedEntry, type KillFeedProps };

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
